public class Element_hasClass_TriageGen1Test {

    private Element element;

    @Before
    public void setUp() {
        element = new Element(Tag.valueOf("div"), "", new Attributes());
    }

    @Test
    public void testHasClass_ExactMatch() {
        element.attr("class", "testClass");
        assertTrue(element.hasClass("testClass"));
        assertFalse(element.hasClass("otherClass"));
    }

    @Test
    public void testHasClass_CaseInsensitiveMatch() {
        element.attr("class", "TestClass");
        assertTrue(element.hasClass("testclass"));
    }

    @Test
    public void testHasClass_NoClassAttribute() {
        assertFalse(element.hasClass("anyClass"));
    }

    @Test
    public void testHasClass_EmptyClassAttribute() {
        element.attr("class", "");
        assertFalse(element.hasClass("anyClass"));
    }

    @Test
    public void testHasClass_MultipleClasses_SingleMatch() {
        element.attr("class", "class1 class2 class3");
        assertTrue(element.hasClass("class2"));
        assertFalse(element.hasClass("class4"));
    }

    @Test
    public void testHasClass_MultipleClasses_CaseInsensitiveMatch() {
        element.attr("class", "Class1 Class2 Class3");
        assertTrue(element.hasClass("class2"));
    }

    @Test
    public void testHasClass_WhitespaceHandling() {
        element.attr("class", " class1  class2  class3 ");
        assertTrue(element.hasClass("class2"));
    }

    @Test
    public void testHasClass_ClassNameShorterThanAttribute() {
        element.attr("class", "short longClass");
        assertTrue(element.hasClass("short"));
        assertFalse(element.hasClass("long"));
    }

    @Test
    public void testHasClass_ClassNameLongerThanAttribute() {
        element.attr("class", "short");
        assertFalse(element.hasClass("longerClass"));
    }

    @Test
    public void testHasClass_TrailingWhitespace() {
        element.attr("class", "testClass ");
        assertTrue(element.hasClass("testClass"));
    }

    @Test
    public void testHasClass_LeadingWhitespace() {
        element.attr("class", " testClass");
        assertTrue(element.hasClass("testClass"));
    }

    @Test
    public void testHasClass_WhitespaceOnlyClass() {
        element.attr("class", "   ");
        assertFalse(element.hasClass("anyClass"));
    }

    @Test
    public void testHasClass_WhitespaceOnlyAndClassName() {
        element.attr("class", " ");
        assertFalse(element.hasClass("anyClass"));
    }
}
